TLM.f("Tempora/Pent16-0",{"officium":"Dominica XVI Post Pentecosten","rule":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"sections":{"Introitus":[{"k":"ref","la":"Ps 85:3; 85:5"},{"k":"text","la":"Miserére mihi, Dómine, quóniam ad te clamávi tota die: quia tu, Dómine, suávis ac mitis es, et copiósus in misericórdia ómnibus invocántibus te."},{"k":"ref","la":"Ps 85:1"},{"k":"text","la":"Inclína, Dómine, aurem tuam mihi, et exáudi me: quóniam inops, et pauper sum ego."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Miserére mihi, Dómine, quóniam ad te clamávi tota die: quia tu, Dómine, suávis ac mitis es, et copiósus in misericórdia ómnibus invocántibus te."}],"Oratio":[{"k":"text","la":"Tua nos, quǽsumus, Dómine, grátia semper et prævéniat et sequátur: ac bonis opéribus júgiter præstet esse inténtos."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Ephésios"},{"k":"ref","la":"Ephes 3:13-21"},{"k":"text","la":"Fratres: Obsecro vos, ne deficiátis in tribulatiónibus meis pro vobis: quæ est glória vestra. Hujus rei grátia flecto génua mea ad Patrem Dómini nostri Jesu Christi, ex quo omnis patérnitas in cœlis et in terra nominátur, ut det vobis secúndum divítias glóriæ suæ, virtúte corroborári per Spíritum ejus in interiórem hóminem, Christum habitáre per fidem in córdibus vestris: in caritáte radicáti et fundáti, ut póssitis comprehéndere cum ómnibus sanctis, quæ sit latitúdo et longitúdo et sublímitas et profúndum: scire étiam supereminéntem sciéntiæ caritátem Christi, ut impleámini in omnem plenitúdinem Dei. Ei autem, qui potens est ómnia fácere superabundánter, quam pétimus aut intellégimus, secúndum virtútem, quæ operátur in nobis: ipsi glória in Ecclésia et in Christo Jesu, in omnes generatiónes sǽculi sæculórum. Amen."}],"Graduale":[{"k":"ref","la":"Ps 101:16-17"},{"k":"text","la":"Timébunt gentes nomen tuum, Dómine, et omnes reges terræ glóriam tuam."},{"k":"text","la":"Quóniam ædificávit Dóminus Sion, et vidébitur in majestáte sua. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Ps 97:1"},{"k":"text","la":"Cantáte Dómino cánticum novum: quia mirabília fecit Dóminus. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam."},{"k":"ref","la":"Luc 14:1-11"},{"k":"text","la":"In illo témpore: Cum intráret Jesus in domum cujúsdam príncipis pharisæórum sábbato manducáre panem, et ipsi observábant eum. Et ecce, homo quidam hydrópicus erat ante illum. Et respóndens Jesus dixit ad legisperítos et pharisǽos, dicens: Si licet sábbato curáre? At illi tacuérunt. Ipse vero apprehénsum sanávit eum ac dimísit. Et respóndens ad illos, dixit: Cujus vestrum ásinus aut bos in púteum cadet, et non contínuo éxtrahet illum die sábbati? Et non póterant ad hæc respóndere illi. Dicebat autem et ad invitátos parábolam, inténdens, quómodo primos accúbitus elígerent, dicens ad illos: Cum invitátus fúeris ad núptias, non discúmbas in primo loco, ne forte honorátior te sit invitátus ab illo, et véniens is, qui te et illum vocávit, dicat tibi: Da huic locum: et tunc incípias cum rubóre novíssimum locum tenére. Sed cum vocátus fúeris, vade, recúmbe in novíssimo loco: ut, cum vénerit, qui te invitávit, dicat tibi: Amíce, ascénde supérius. Tunc erit tibi glória coram simul discumbéntibus: quia omnis, qui se exáltat, humiliábitur: et qui se humíliat, exaltábitur."}],"Offertorium":[{"k":"ref","la":"Ps 39:14; 39:15"},{"k":"text","la":"Dómine, in auxílium meum réspice: confundántur et revereántur, qui quærunt ánimam meam, ut áuferant eam: Dómine, in auxílium meum réspice."}],"Secreta":[{"k":"text","la":"Munda nos, quǽsumus, Dómine, sacrifícii præséntis efféctu: et pérfice miserátus in nobis; ut ejus mereámur esse partícipes."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 70:16-17; 70:18"},{"k":"text","la":"Dómine, memorábor justítiæ tuæ solíus: Deus, docuísti me a juventúte mea: et usque in senéctam et sénium, Deus, ne derelínquas me."}],"Postcommunio":[{"k":"text","la":"Purífica, quǽsumus, Dómine, mentes nostras benígnus, et rénova cœléstibus sacraméntis: ut consequénter et córporum præsens páriter et futúrum capiámus auxílium."},{"k":"macro","name":"Per Dominum"}]},"hr":{"dd0b5791417e8e12":{"t":"Ps 85, 3 i 5, Ps 85, 1\n(Ps 85, 3 i 5) Smiluj mi se, Gospodine, jer neprestano vapijem k tebi! Ti si, Gospodine, dobrostiv i blag, pun milosrđa za sve koji te zazivlju. (Ps 85, 1) Prikloni, Gospodine, uho svoje i usliši me, jer sam bijedan i siromašan.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 85, 3 i 5) Smiluj mi se, Gospodine, jer neprestano vapijem k tebi! Ti si, Gospodine, dobrostiv i blag, pun milosrđa za sve koji te zazivlju.","kn":"(Ps. 85, 3, 5). Smiluj mi se, Gospodine, jer k Tebi vapijem čio dan; jer Ti si, Gospodine, blag i dobar i veoma milostiv svima, koji te zazivaju. (Ps, 85, 1) Prikloni, Gospodine, uho svoje i uslišl me, jer sam ubog i siromah. Slava Ocu . . -. Smiluj mi se . . .","knRef":"Kniewald 1942, str. 404–405 (snimka 203) (OCR)"},"4499d3f4919668fd":{"t":"<i>Pomolimo se</i>.\nTvoja milost, molimo, Gospodine, neka nas uvijek pretječe i prati te neprestano potiče na dobra djela.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Tvojom nas, molimo, ^Gospodine, milcšću uvijek i pretječi i prati da v-azda prežemo za dobrim djelima, po G. n.","knRef":"Kniewald 1942, str. 404–405 (snimka 203) (OCR)"},"a6fda0623aa8b4e7":{"t":"Ef 3, 13-21\nČitanje Poslanice bl. Pavla apostola Efežanima. Braćo, molim vas da ne klonete zbog mojih nevolja, što ih trpim za vas. One su vaša slava. Prigibam svoja koljena pred Ocem našega Gospodina Isusa Krista, od koga potječe svako očinstvo na nebu i na zemlji, sa svrhom, da vam po svojoj obilnoj slavi dade da se njegovim Duhom ojačate za unutrašnjeg čovjeka; da po vjeri Krist stanuje u vašim srcima; da možete u ljubavi ukorijenjeni i utvrđeni sa svima svetima razumjeti širinu i dužinu i visinu i dubinu (ljubavi Kristove) i spoznati ljubav Kristovu koja nadilazi svaku spoznaju, da se napunite svake punine Božje. Onome koji snagom što djeluje u nama može učiniti neizmjerno više nego što mi molimo ili razumijemo: njemu slava u Crkvi i u Isusu Kristu od svih pokoljenja u vjeke vjekova. Amen.","kn":"Čitanje poslanice bi. Pavla apostola Efežanima (3, 13-21). Braćo! Molimo vas, da ne klonete radi mojih nevolja, koje trpim za vas, što je vaša slava. Zato prigiibam svoja koljena pred Ocem Gospodina našega Isusa Krista, po kojemu postaje' svaka obitelj na nebu i na zemlji, da vam po svojoj' obilnoj slavi i doibroti dadne, da se po njegovu duhu pojačate za unutrašnjega čovjeka, da po vjeri Krist stanuje u vašim srcima. Da ukorijenjeni i utvrđeni u ljubavi sa svima svetima možete dokučiti, koja je širina i dužina i visina. i dubina i da možete poznati Kristovu ljubav, koja prelazi svako znanje, da se napunite svakim Božjim obiljem. On može po moći, koja djeluje u nama, učiniti heizi mjerno više, nego što mi molimo ili razumijemo. Njem'U neka bude slava u Crkvi i u Isusu Kristu od svih naraštaja u vijeke vjekova, Amen.","knRef":"Kniewald 1942, str. 404–405 (snimka 203) (OCR)"},"b7134eb33fda9614":{"t":"Ps 101, 16-17\nNarodi će se bojati imena tvojega, Gospodine, i svi kraljevi zemaljski slave tvoje. Jer je Gospodin sagradio Sion i javio se u slavi svojoj.\n\nPs 97, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nPjevajte Gospodinu pjesmu novu, jer učini čudesa. <i>Aleluja</i>.","kn":"(Ps. 101, 16, 17). .Bojat će se narodi imena Tvojega, Gospodine, i svi. kraljevi zemaljski slave Tvoje; kada Gosipodin sagradi Slon i javi se u slavi svojoj.\n\nAleluja, aleluja. (Ps. 97, 1) Pjevajte Gospodinu pjesmu novu, jer divne stvari učini Gospodin.","knRef":"Kniewald 1942, str. 404–405 (snimka 203) (OCR)"},"9d99a00693e2b9ce":{"t":"Lk 14, 1-11\nSlijedi sveto Evanđelje po Luki. U ono vrijeme vrebali su na Isusa, kad jedne subote dođe u kuću nekoga farizejskog poglavice da blaguje. I gle, pred njim je stajao neki čovjek koji je imao vodenu bolest. Isus upita zakonoznance i farizeje: Je li dopušteno ozdravljati u subotu? Oni su šutjeli. Tada se Isus rukom dotakne bolesnika, izliječi ga i otpusti. Onda njima reče: Koji od vas ne bi u subotinji dan izvukao svojega magarca ili vola, kada bi mu pao u zdenac? Na to mu nisu mogli ništa odgovoriti. K tome, kad je vidio kako uzvanici biraju prva mjesta, reče usporedbu: Kad te tko pozove na svadbu, ne sjedaj na prvo mjesto, da ne bi među uzvanicima bio koji časniji od tebe, pa da ne bi došao onaj koji je pozvao tebe i njega i rekao ti: Daj mjesto ovome! Tada bi postiđen morao sjesti na posljednje mjesto. Nego, kada te tko pozove, pođi i sjedni na posljednje mjesto, da ti onaj, koji te je pozvao, kada dođe, reče: Prijatelju, pomakni se naviše! To će ti tada biti na čast pred svim uzvanicima. Kažem vam: svaki koji se uzvisuje ponizit će se, a koji se ponizuje uzvisit će se.","kn":"t Slijedi sveto evanđelje po Luki (14,. 1-11). U ono vrijeme vrebali su na Isusa, kad je u subotu ušao u kuću nekoga farizejskog poglavice, da jede kruh. I pred njim^. je .stajao čovjek, koji je imao vodenu bolest. Isus. tada upita zakonoznance i farizeje: Je li slobodno liječiti u subotu? Oni su šutjeli, a on se ga dotače, izliječi ga i otpusti. Nato ih upita: Koji od vas ne bi na subotnji dan izvukao svoga magarca ili Vola, kad bi mu pao U zdenac? Oni mu na to nijesu mogli odgovoriti. Kad je vidio, kako uzvanici biraju,, prva mjesta, reče . im prispodobu: Kadate tko pozove na svadbu, ne .sjedaj na jprvo mjesto, da ne bi među uzvanicima . bio koji časniji od tebe, i da ne bi došao-, koji je pozvao tebe i njega i kazao ti:‘ Daj\" mjesto ovomu! Tada bi sa stidom morao sjesti na posljednje mjesto. Nego, kada te tko pozove, pođi i sjedni na. posljednje mjesto, da kada dođe onaj, koji te je pozvao, reče ti: Prijatelju, pomakni se gore! Tada će ti biti čast pred onima, koji sjede zajedno s tobc-m. Jer svaki, koji se uzvisuje,, ponizit će se, ,a koji se ponizuje, uzvisit će se. -i' ..","knRef":"Kniewald 1942, str. 404–405 (snimka 203) (OCR)"},"2a623c32d2a72b7d":{"t":"Ps 39, 14 i 15\nGospodine, pohiti da mi pomogneš! Neka se smetu i postide svi koji traže dušu moju da je pogube. Gospodine, pohiti da mi pomogneš.","kn":"^ (Ps. 39. 14, 15). Gospodine, pohiti da ml^pomogneš! Nek se zaslide i smetu ujedno, koji traže dušu moju da je uzmu. Gospodine, pohiti da mi pomogneš!","knRef":"Kniewald 1942, str. 144–145 (snimka 73) (OCR)"},"3b89e1e837f358aa":{"t":"Očisti nas, molimo, Gospodine, snagom ove žrtve i milostivo djeluj u nama tako da joj budemo vrijedni dionici.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Očisti nas, molimo, Gospodine, učinkom ove žrtve i milostiv dovrši u nama, da zavrijedimo biti njezini dionici, po G. n.'","knRef":"Kniewald 1942, str. 406–407 (snimka 204) (OCR)"},"adad0f7f2fcbfa9b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože. – Ti si s jedinorođenim Sinom tvojim i s Duhom Svetim jedan Bog, jedan Gospodin, ne u jedinstvu jedne osobe, već u Trojstvu jedine biti. Što naime po tvojoj objavi vjerujemo o tvojoj slavi, to isto bez razlike i razlučivanja vjerujemo i o tvome Sinu i o Duhu Svetome. Tako se u ispovijedanju istinitog i vjekovječnog božanstva klanjamo i vlastitosti osoba i jedinstvu biti i jednakosti veličanstva. – Koje hvale anđeli i arkanđeli, kerubini i serafini koji ne prestaju svaki dan klicati govoreći složnim glasom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Go. spodine sveti, Oće svemogući, vječni Bože, koji si sa Sinom svojim i s Duhom Svetim jedan Bog i je- dan Gospodin: ne u jedinstvu osobe, nego u Trojstvu jedne biti. Jer sve, što po Tvojem otkrivenju vjerujemo o Tvojoj slavi, to bez razlike i razlučivanja mislimo i o Sinu Tvoj emu i o Duhu Svetomu. Ispovijedajući pravo i vječno Božanstvo, klanjamo se tako i vlastitosti u osobama i jedinstvu u biti i jednakosti u veličanstvu, koje hvale anđeli i arkanđeli, kerubini i serafini, koji ne prestaju klicati svakog dana jednoglasno govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"ebaa7bfab4895b3c":{"t":"Ps 70, 16-17 i 18\nGospodine, slavit ću samo tvoju pravdu! Bože, ti si me učio od mladosti moje, pa sve do duboke starosti ne zapusti me, Bože.","kn":"(Ps. 70, 16-13), Gospodine, opominjat ću se samo Tvoje pravednosti: Bože, Ti si me učio od mladosti moje, i sve do kasne starosti: Bože, nemoj me ostaviti!","knRef":"Kniewald 1942, str. 406–407 (snimka 204) (OCR)"},"b20fdd5a2c32249e":{"t":"<i>Pomolimo se</i>.\nDuše naše, molimo, Gospodine, milostivo očisti i obnovi nebeskim otajstvima, da tako primimo sadašnju pomoć za tijelo kao i buduću.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Očisti, molimo. Gospodine, dobrostivo duše naše i nebeskim ih tajnama obnovi, da dosljedno 1 sadašnju primamo pomoć u tijelu, kao i buduću, po G. n.","knRef":"Kniewald 1942, str. 406–407 (snimka 204) (OCR)"}}});
